CREATE OR REPLACE FUNCTION public.vip_my_trends(p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_prog uuid; v_streak int := 0; r record; v_out jsonb;
begin
  select programme_id into v_prog from public.vip_members where profile_id = public.vip_who();
  if v_prog is null then return null; end if;
  v_out := public.vip_trend_core(v_prog, public.vip_who(), p_days);
  for r in select s.videos from public.vip_statements s join public.vip_months mo on mo.id = s.month_id
            where s.profile_id = public.vip_who() and s.status <> 'void' and mo.status = 'closed' order by mo.year desc, mo.month desc loop
    exit when r.videos < 1;
    v_streak := v_streak + 1;
  end loop;
  return v_out || jsonb_build_object('streak_months', v_streak);
end $function$;
